function teamList(def){return def.clubs.map((name,i)=>({name,badge:['🦁','🦅','🐯','⭐','🔥','⚡','🐺','👑','🌪️','🛡️'][i%10],strength:69+((i*7+def.id.length*3)%24),country:def.country,league:def.id,stadium:name.split(' ')[0]+' Cricket Ground'}));}
const worldTeams=Object.fromEntries(leagueDefs.map(l=>[l.id,teamList(l)]));
function clone(x){return JSON.parse(JSON.stringify(x));}
function money(k){const n=Math.max(0,Math.round(k*1000));if(n>=1e9)return '₹'+(n/1e9).toFixed(2).replace(/0+$/,'').replace(/\.$/,'')+'B';if(n>=1e6)return '₹'+(n/1e6).toFixed(2).replace(/0+$/,'').replace(/\.$/,'')+'M';if(n>=1e3)return '₹'+(n/1e3).toFixed(n>=1e5?0:1).replace(/\.0$/,'')+'K';return '₹'+n.toLocaleString('en-IN');}
function rupees(n){return '₹'+Math.round(n||0).toLocaleString('en-IN');}
function avg(arr,key='rating'){return arr.length?arr.reduce((s,x)=>s+(Number(x[key])||0),0)/arr.length:0;}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function freshState(slot=1){return{version:6,slot,managerName:'',managerRating:65,boardConfidence:70,gameDay:1,season:2027,activeLeague:'ICT',club:null,players:[],budget:5000,fans:250,weeklySalary:1255,managerWallet:0,lastSalaryDay:0,wins:0,losses:0,careerWins:0,careerLosses:0,played:0,careerTrophies:0,careerClubs:[],careerTimeline:[],morale:70,mentality:'Balanced',tactics:{batting:'Balanced',bowling:'Mixed',powerplay:'Balanced',death:'Yorkers',field:'Balanced',captain:''},academyLevel:1,youth:[],stadiumLevel:1,scoutReports:[],news:[],fixtures:[],round:0,seasonStage:'league',playoffs:[],playoffIndex:0,table:{},jobOffers:[],lastProposalDay:0,proposal:null,format:'T20',difficulty:'realistic',seasonAwards:[],lastPressDay:0};}
let activeSlot=Number(localStorage.getItem('cm27_v05_active_slot')||localStorage.getItem('cm27_v04_active_slot')||1);if(![1,2,3].includes(activeSlot))activeSlot=1;
function loadSlot(slot){try{const raw=localStorage.getItem(SAVE_PREFIX+slot)||localStorage.getItem('cm27_v05_slot_'+slot)||localStorage.getItem('cm27_v04_slot_'+slot);if(raw){const s=JSON.parse(raw);return migrate({...freshState(slot),...s,slot,club:s.club||null,tactics:{...freshState(slot).tactics,...(s.tactics||{})}});} }catch(e){console.warn('Save could not be loaded',e);}return freshState(slot);}
function migrate(s){if(s.version<4){const oldName=s.club?.name;const def=leagueDefs.find(x=>x.id==='ICT');const teams=worldTeams.ICT;s.club=teams.find(t=>t.name===oldName)||teams[0];s.activeLeague='ICT';s.news=['CM 27 V0.4 career migration complete. Club identities are now fixed.',...(s.news||[])];s.players=(s.players?.length?s.players:startingSquad()).map(p=>({...p,form:p.form??70,morale:p.morale??70}));s.budget=s.budget??5000;s.managerRating=s.managerRating??65;s.morale=70;s.version=4;}if(!s.club){s.club=worldTeams[s.activeLeague]?.[0]||worldTeams.ICT[0];}if(!s.players?.length)s.players=startingSquad();if(!s.fixtures?.length&&s.managerName)setupSeason(s);return s;}
function startingSquad(){return[{id:1,name:'Arjun Sen',role:'Batter',age:25,rating:82,value:1400,form:74,morale:75},{id:2,name:'Kabir Das',role:'Fast Bowler',age:27,rating:79,value:1200,form:70,morale:72},{id:3,name:'Rohan Mehta',role:'All-rounder',age:23,rating:84,value:1600,form:78,morale:80},{id:4,name:'Dev Malhotra',role:'Wicketkeeper',age:24,rating:76,value:900,form:69,morale:70},{id:5,name:'Ishaan Roy',role:'Spinner',age:29,rating:81,value:1100,form:72,morale:74},{id:6,name:'Ayaan Kapoor',role:'Batter',age:22,rating:88,value:2100,form:77,morale:75},{id:7,name:'Rehan Bose',role:'Fast Bowler',age:23,rating:81,value:1300,form:73,morale:73},{id:8,name:'Ethan Cole',role:'All-rounder',age:25,rating:87,value:2300,form:80,morale:78},{id:9,name:'Aarav Nair',role:'Spinner',age:22,rating:80,value:1100,form:70,morale:75},{id:10,name:'Sameer Gill',role:'Wicketkeeper',age:26,rating:84,value:1700,form:76,morale:77},{id:11,name:'Kunal Saha',role:'Batter',age:24,rating:79,value:900,form:71,morale:74},{id:12,name:'Daniel Brooks',role:'Fast Bowler',age:29,rating:89,value:2600,form:82,morale:79}];}
let state=loadSlot(activeSlot);let proposalTarget=null;
function save(){localStorage.setItem(SAVE_PREFIX+activeSlot,JSON.stringify(state));localStorage.setItem('cm27_v05_active_slot',String(activeSlot));renderAll();}
function addNews(text,category='CLUB NEWS'){state.news.unshift({day:state.gameDay,category,text});state.news=state.news.slice(0,30);}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2600);}
function teamRating(team=state.players){return Math.round(avg(team)*10)/10;}
function activeDef(){return leagueDefs.find(l=>l.id===state.activeLeague)||leagueDefs[0];}
function activeTeams(){return worldTeams[state.activeLeague]||worldTeams.ICT;}
function clubStrength(){return Math.round((teamRating()+avg(state.players,'form')*.08+state.morale*.04)*10)/10;}
function newTable(teams){return Object.fromEntries(teams.map(t=>[t.name,{name:t.name,played:0,wins:0,losses:0,points:0,runsFor:0,runsAgainst:0,strength:t.strength||70}]));}
function makeRounds(teams){const a=teams.slice(),rounds=[];if(a.length%2)a.push(null);const n=a.length;for(let r=0;r<n-1;r++){const games=[];for(let i=0;i<n/2;i++){const x=a[i],y=a[n-1-i];if(x&&y)games.push({home:r%2?y.name:x.name,away:r%2?x.name:y.name,played:false});}rounds.push(games);a.splice(1,0,a.pop());}return rounds;}
function setupSeason(s=state){const teams=worldTeams[s.activeLeague]||worldTeams.ICT;const own=teams.find(t=>t.name===s.club?.name);if(!own){s.club=teams[0];}s.table=newTable(teams);s.fixtures=makeRounds(teams);s.round=0;s.seasonStage='league';s.playoffs=[];s.playoffIndex=0;s.seasonAwards=[];}
function showPage(p){document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id===p+'Page'));document.querySelectorAll('.nav-link').forEach(x=>x.classList.toggle('active',x.dataset.page===p));const labels={dashboard:'Dashboard',competitions:'World Competitions',club:'My Club',squad:'Your Squad',transfers:'Transfer Market',tactics:'Match Tactics',matches:'Match Centre',scouting:'Scouting Network',academy:'Youth Academy',morale:'Dressing Room',press:'Press Room',stadium:'Stadium Development',legacy:'Manager Legacy',jobs:'Manager Proposals'};document.getElementById('pageTitle').textContent=labels[p]||'Dashboard';document.getElementById('pageEyebrow').textContent=p==='dashboard'?'YOUR CAREER':'CLUB MANAGEMENT';window.scrollTo({top:0,behavior:'smooth'});}
document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>showPage(b.dataset.page)));document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>showPage(b.dataset.go)));
function renderStartOptions(){const l=document.getElementById('startLeagueSelect');l.innerHTML=leagueDefs.map(x=>`<option value="${x.id}">${x.flag} ${x.name} · ${x.size} clubs</option>`).join('');renderStartClubs();l.addEventListener('change',renderStartClubs);}
function renderStartClubs(){const id=document.getElementById('startLeagueSelect').value||'ICT';document.getElementById('startClubSelect').innerHTML=(worldTeams[id]||worldTeams.ICT).map(t=>`<option value="${esc(t.name)}">${t.badge} ${esc(t.name)} · ${t.strength} OVR</option>`).join('');}
function startCareer(e){e.preventDefault();const name=document.getElementById('managerNameInput').value.trim();if(!name)return;const slot=Number(document.getElementById('startSaveSlot').value);activeSlot=slot;state=freshState(slot);v05EnsureState();state.managerName=name;state.activeLeague=document.getElementById('startLeagueSelect').value;state.club=activeTeamsFor(state.activeLeague).find(t=>t.name===document.getElementById('startClubSelect').value);state.managerStatuses[state.club.name]='Player Manager';state.players=startingSquad();state.weeklySalary=1255+Math.round((state.club.strength-70)*90);state.budget=5000+Math.round((state.club.strength-70)*80);state.careerClubs=[state.club.name];state.careerTimeline=[`Day 1 · Appointed manager of ${state.club.name}.`];addNews(`${name} appointed manager of ${state.club.name}.`,'APPOINTMENT');setupSeason();document.getElementById('careerSetup').classList.add('hidden');save();toast('Your CM 27 career has started.');}
function activeTeamsFor(id){return worldTeams[id]||worldTeams.ICT;}
document.getElementById('careerSetupForm').addEventListener('submit',startCareer);renderStartOptions();
function nextFixture(){if(state.seasonStage==='league'){if(state.round>=state.fixtures.length)return null;return state.fixtures[state.round].find(f=>f.home===state.club.name||f.away===state.club.name&&!f.played)||state.fixtures[state.round].find(f=>(f.home===state.club.name||f.away===state.club.name)&&!f.played)||null;}if(state.seasonStage==='playoffs'){return state.playoffs[state.playoffIndex]||null;}return null;}
function standings(){return Object.values(state.table||{}).sort((a,b)=>b.points-a.points||(b.runsFor-b.runsAgainst)-(a.runsFor-a.runsAgainst)||b.wins-a.wins);}
function matchChance(a,b,home=false){const diff=(a-b)+(home?2:0);return Math.max(.12,Math.min(.88,.5+diff*.018));}
function inningsScore(bat,bowl,format,tactics={},pitch='Balanced',homeBonus=0){const overs=format==='ODI'?50:20;let batMod=0,bowlMod=0;if(tactics.batting==='Aggressive')batMod+=5; if(tactics.batting==='Defensive')batMod-=4;if(tactics.powerplay==='Attack')batMod+=3;if(tactics.powerplay==='Protect')batMod-=2;if(tactics.bowling==='Pace'&&pitch==='Bowling')bowlMod+=3;if(tactics.bowling==='Spin'&&pitch==='Spin')bowlMod+=4;if(tactics.bowling==='Contain')bowlMod+=2;if(tactics.death==='Yorkers')bowlMod+=2;if(tactics.death==='Defend')bowlMod+=1;if(tactics.death==='Attack')bowlMod-=1;if(tactics.field==='Attacking')bowlMod+=2;if(tactics.field==='Defensive')bowlMod+=1;if(pitch==='Batting')batMod+=4;if(pitch==='Bowling')bowlMod+=3;if(pitch==='Spin')bowlMod+=2;const base=format==='ODI'?245:158;const score=Math.max(format==='ODI'?110:65,Math.round(base+(bat-bowl)*1.12+batMod-bowlMod+homeBonus+(Math.random()*52-25)));const wickets=Math.min(10,Math.max(1,Math.round(4.8+(bowl-bat)/10+(Math.random()*4-1.5)+(tactics.batting==='Aggressive'?1:0))));return{runs:score,wickets,overs:format==='ODI'?50:20};}
function simulatePair(home,away,format='T20',homeClub=false){const ht=teamForName(home),at=teamForName(away);const hs=ht.strength+(homeClub?clubStrength()-teamRating():0),as=at.strength+(away===state.club.name?clubStrength()-teamRating():0);const winHome=Math.random()<matchChance(hs,as, true);const winner=winHome?home:away;const loser=winHome?away:home;const hscore=inningsScore(hs,as,format,{},'Balanced',1);const ascore=inningsScore(as,hs,format,{},'Balanced',0);return{home,away,homeScore:hscore,awayScore:ascore,winner,loser};}
function teamForName(name){if(name===state.club?.name)return{name,badge:state.club.badge,strength:clubStrength()};for(const arr of Object.values(worldTeams)){const found=arr.find(t=>t.name===name);if(found)return found;}return{name,badge:'🏏',strength:70};}
function updateTable(result){const h=state.table[result.home],a=state.table[result.away];if(!h||!a)return;h.played++;a.played++;h.runsFor+=result.homeScore.runs;h.runsAgainst+=result.awayScore.runs;a.runsFor+=result.awayScore.runs;a.runsAgainst+=result.homeScore.runs;if(result.winner===result.home){h.wins++;h.points+=2;a.losses++;}else{a.wins++;a.points+=2;h.losses++;}}
function userTactics(){return{...state.tactics};}
function playUserFixture(f){const home=f.home===state.club.name,oppName=home?f.away:f.home,opp=teamForName(oppName),format=document.getElementById('matchFormat').value,pitch=document.getElementById('pitchCondition').value;const own=clubStrength(),opponent=opp.strength;const tactics=userTactics();const batBonus=tactics.batting==='Aggressive'?5:tactics.batting==='Defensive'?-4:0;const bowlBonus=(tactics.bowling==='Pace'?2:tactics.bowling==='Spin'?2:tactics.bowling==='Contain'?3:0)+(tactics.death==='Yorkers'?2:tactics.death==='Defend'?1:-1)+(tactics.field==='Attacking'?2:tactics.field==='Defensive'?1:0);const homeBonus=home?2+(state.stadiumLevel-1)*.6:0;const ownBat=inningsScore(own+batBonus,opponent,format,tactics,pitch,homeBonus);const oppBat=inningsScore(opponent,own+bowlBonus,format,{},pitch,0);let userWon=ownBat.runs>oppBat.runs;const probability=matchChance(own+batBonus+bowlBonus,opponent,home);if(Math.abs(ownBat.runs-oppBat.runs)<7)userWon=Math.random()<probability;else if(Math.abs(own-opponent)>14&&Math.random()<.16)userWon=!userWon;const ownScore={runs:userWon?Math.max(ownBat.runs,oppBat.runs+1):Math.min(ownBat.runs,oppBat.runs-1),wickets:ownBat.wickets};const oppScore={runs:userWon?Math.min(oppBat.runs,ownScore.runs-1):Math.max(oppBat.runs,ownScore.runs+1),wickets:oppBat.wickets};const result=home?{home:state.club.name,away:oppName,homeScore:ownScore,awayScore:oppScore,winner:userWon?state.club.name:oppName}:{home:oppName,away:state.club.name,homeScore:oppScore,awayScore:ownScore,winner:userWon?state.club.name:oppName};return{result,userWon,opponent:oppName,format,ownScore,oppScore};}
function finishUserMatch(f,stageLabel='LEAGUE'){const outcome=playUserFixture(f),r=outcome.result;if(state.seasonStage==='league')updateTable(r);f.played=true;f.result=r;state.played++;state.careerWins+=outcome.userWon?1:0;state.careerLosses+=outcome.userWon?0:1;state.wins+=outcome.userWon?1:0;state.losses+=outcome.userWon?0:1;const prize=outcome.userWon?(outcome.format==='ODI'?560:450):(outcome.format==='ODI'?180:140);state.budget+=prize;state.fans=Math.max(0,state.fans+(outcome.userWon?Math.round(18+state.managerRating*.6):-Math.round(5+Math.random()*10)));state.managerRating=Math.max(1,Math.min(100,state.managerRating+(outcome.userWon?2:-1)));state.boardConfidence=Math.max(0,Math.min(100,state.boardConfidence+(outcome.userWon?4:-4)));state.morale=Math.max(15,Math.min(100,state.morale+(outcome.userWon?5:-5)));state.players.forEach(p=>{const formShift=(outcome.userWon?2:-1)+(Math.random()*4-2);p.form=Math.max(35,Math.min(100,Math.round((p.form||70)+formShift)));p.morale=Math.max(10,Math.min(100,(p.morale||70)+(outcome.userWon?3:-3)));p.lastMatchRating=Math.max(4,Math.min(10,Number((6.1+Math.random()*2+(outcome.userWon?.5:0)).toFixed(1))));});const margin=Math.abs(outcome.ownScore.runs-outcome.oppScore.runs);addNews(`${outcome.userWon?'Victory':'Defeat'}: ${state.club.name} ${outcome.ownScore.runs}/${outcome.ownScore.wickets} vs ${outcome.opponent} ${outcome.oppScore.runs}/${outcome.oppScore.wickets} (${outcome.format}).`,'MATCH RESULT');state.careerTimeline.unshift(`Day ${state.gameDay} · ${outcome.userWon?'Won':'Lost'} against ${outcome.opponent}.`);renderMatchReport(outcome,stageLabel,margin);if(outcome.userWon){maybeAwardPressPrompt();}else{setPressPrompt('The club has suffered a setback. How will you respond?', [['Take responsibility',2,2],['Demand a stronger performance',-1,-2],['Stay calm and focus on training',1,1]]);}paySalary();save();}
function renderMatchReport(o,stage,margin){const box=document.getElementById('matchResult');box.classList.remove('hidden');box.innerHTML=`<div class="eyebrow">${esc(activeDef().short)} · ${esc(stage)} · MATCH REPORT</div><h3 class="${o.userWon?'result-win':'result-loss'}">${o.userWon?'VICTORY':'DEFEAT'}</h3><div class="scoreline"><b>${esc(state.club.name)}</b><strong>${o.ownScore.runs}/${o.ownScore.wickets}</strong><span>vs</span><strong>${o.oppScore.runs}/${o.oppScore.wickets}</strong><b>${esc(o.opponent)}</b></div><p>${o.userWon?`You won by ${margin} runs.`:`You lost by ${margin} runs.`}<br><b class="reward-text">${o.userWon?'+':'+'}${money(o.userWon?(o.format==='ODI'?560:450):(o.format==='ODI'?180:140))} club reward</b><br>Team rating: ${clubStrength()} · Manager rating: ${state.managerRating}/100</p>`;const ratings=document.getElementById('playerMatchRatings');ratings.classList.remove('hidden');ratings.innerHTML='<div class="eyebrow">PLAYER PERFORMANCE</div><h3>Top performers</h3><div class="rating-list">'+state.players.slice().sort((a,b)=>(b.lastMatchRating||0)-(a.lastMatchRating||0)).slice(0,5).map(p=>`<div><span>${esc(p.name)}</span><b>${p.lastMatchRating||'—'}/10</b></div>`).join('')+'</div>';}
function simulateAIFixture(f){const r=simulatePair(f.home,f.away,document.getElementById('matchFormat')?.value||'T20');f.played=true;f.result=r;updateTable(r);}
function advanceLeagueRound(){const round=state.fixtures[state.round];if(!round)return;round.forEach(f=>{if(!f.played)simulateAIFixture(f);});state.round++;if(state.round>=state.fixtures.length){beginPlayoffs();}else{addNews(`${activeDef().short}: Round ${state.round} completed. Updated standings are live.`,'LEAGUE UPDATE');}}
function beginPlayoffs(){const top=standings().slice(0,4);if(top.length<4){state.seasonStage='complete';return;}state.seasonStage='playoffs';state.playoffs=[{name:'Qualifier 1',home:top[0].name,away:top[1].name,played:false,winner:null},{name:'Eliminator',home:top[2].name,away:top[3].name,played:false,winner:null}];state.playoffIndex=0;addNews(`${activeDef().short}: League stage complete. ${top.map((t,i)=>`${i+1}. ${t.name}`).join(', ')} qualify for playoffs.`,'PLAYOFFS');advancePlayoffsAuto();}
function playOffResult(f){const r=simulatePair(f.home,f.away,'T20');f.played=true;f.winner=r.winner;f.result=r;return r;}
function advancePlayoffsAuto(){while(state.seasonStage==='playoffs'&&state.playoffIndex<state.playoffs.length){const f=state.playoffs[state.playoffIndex];if(f.played){state.playoffIndex++;continue;}if(f.home===state.club.name||f.away===state.club.name)break;const r=playOffResult(f);addNews(`${f.name}: ${r.winner} defeated ${r.loser}.`,'PLAYOFF RESULT');state.playoffIndex++;if(state.playoffIndex===2){const q1=state.playoffs[0],el=state.playoffs[1];state.playoffs.push({name:'Qualifier 2',home:q1.loser|| (q1.winner===q1.home?q1.away:q1.home),away:el.winner,played:false,winner:null});}if(state.playoffIndex===3){state.playoffs.push({name:'Grand Final',home:state.playoffs[0].winner,away:state.playoffs[2].winner,played:false,winner:null});}}
 if(state.playoffIndex>=state.playoffs.length&&state.playoffs.length>=4)completeSeason();renderAll();}
function playCurrentMatch(){if(state.seasonStage==='league'){const f=nextFixture();if(!f){advanceLeagueRound();save();return;}const round=state.fixtures[state.round];finishUserMatch(f,`ROUND ${state.round+1}`);round.forEach(x=>{if(!x.played)simulateAIFixture(x);});state.round++;if(state.round>=state.fixtures.length)beginPlayoffs();}else if(state.seasonStage==='playoffs'){advancePlayoffsAuto();const f=state.playoffs[state.playoffIndex];if(!f){completeSeason();save();return;}if(f.home!==state.club.name&&f.away!==state.club.name){advancePlayoffsAuto();save();return;}const outcome=playUserFixture(f);f.played=true;f.winner=outcome.userWon?state.club.name:outcome.opponent;f.loser=outcome.userWon?outcome.opponent:state.club.name;f.result=outcome.result;state.played++;state.careerWins+=outcome.userWon?1:0;state.careerLosses+=outcome.userWon?0:1;state.wins+=outcome.userWon?1:0;state.losses+=outcome.userWon?0:1;state.managerRating=Math.max(1,Math.min(100,state.managerRating+(outcome.userWon?3:-2)));state.boardConfidence=Math.max(0,Math.min(100,state.boardConfidence+(outcome.userWon?6:-5)));state.morale=Math.max(10,Math.min(100,state.morale+(outcome.userWon?6:-6)));state.budget+=outcome.userWon?650:200;addNews(`${f.name}: ${f.winner} ${outcome.userWon?'advanced':'won the tie'} against ${f.loser}.`,'KNOCKOUT');renderMatchReport(outcome,f.name,Math.abs(outcome.ownScore.runs-outcome.oppScore.runs));state.playoffIndex++;if(state.playoffIndex===2){const q1=state.playoffs[0],el=state.playoffs[1];state.playoffs.push({name:'Qualifier 2',home:q1.loser,away:el.winner,played:false,winner:null});}else if(state.playoffIndex===3){state.playoffs.push({name:'Grand Final',home:state.playoffs[0].winner,away:state.playoffs[2].winner,played:false,winner:null});}else if(state.playoffIndex>=4){completeSeason();}advancePlayoffsAuto();}paySalary();save();}
function completeSeason(){if(state.seasonStage==='complete')return;const champ=state.playoffs[3]?.winner||state.club.name;addNews(`${activeDef().name}: ${champ} are the season champions!`,'CHAMPIONS');if(champ===state.club.name){state.careerTrophies++;state.budget+=activeDef().prize;state.managerRating=Math.min(100,state.managerRating+5);state.boardConfidence=Math.min(100,state.boardConfidence+12);state.careerTimeline.unshift(`Season ${state.season} · Won the ${activeDef().short} championship.`);}state.seasonAwards.push({season:state.season,league:state.activeLeague,champion:champ});state.seasonStage='complete';toast(champ===state.club.name?'CHAMPIONS! Your club lifted the trophy.':`${champ} won the championship.`);}
function startNextSeason(){state.season++;state.wins=0;state.losses=0;state.played=0;state.gameDay+=1;state.seasonStage='league';setupSeason();addNews(`${activeDef().short} Season ${state.season} begins. New campaign, new targets.`,'SEASON START');save();}
function paySalary(){const weeks=Math.floor((state.gameDay-state.lastSalaryDay)/7);if(weeks>0){const amount=weeks*state.weeklySalary;state.managerWallet+=amount;state.lastSalaryDay+=weeks*7;addNews(`Manager salary paid: ${rupees(amount)}.`,'FINANCE');}}
function renderTable(){const rows=standings();document.getElementById('leagueTableBody').innerHTML=rows.map((t,i)=>`<tr><td>${i+1}</td><td>${esc(t.name)}${t.name===state.club.name?' <b class="you-tag">YOU</b>':''}</td><td>${t.played}</td><td>${t.wins}</td><td><b>${t.points}</b></td></tr>`).join('');const upcoming=document.getElementById('upcomingFixtures');const fs=state.fixtures.slice(state.round,state.round+3).flat().filter(f=>!f.played).slice(0,5);upcoming.innerHTML=fs.map(f=>`<div class="fixture-row"><span>${esc(f.home)}</span><b>vs</b><span>${esc(f.away)}</span></div>`).join('')||'<p class="muted">League stage completed. Check the knockout bracket.</p>';}
function renderFixture(){const f=nextFixture();let opponent='Season complete',badge='🏆',rating='—',venue='FINISHED';if(f){const home=f.home===state.club.name;opponent=home?f.away:f.home;const t=teamForName(opponent);badge=t.badge;rating=t.strength;venue=home?'HOME':'AWAY';}['fixtureMyName','matchMyName'].forEach(id=>document.getElementById(id).textContent=state.club?.name||'Your club');['fixtureMyLogo','matchMyLogo'].forEach(id=>document.getElementById(id).textContent=state.club?.badge||'🏏');['fixtureOpponentName','matchOpponentName'].forEach(id=>document.getElementById(id).textContent=opponent);['fixtureOpponentLogo','matchOpponentLogo'].forEach(id=>document.getElementById(id).textContent=badge);document.getElementById('fixtureOpponentVenue').textContent=venue;document.getElementById('myTeamRating').textContent=`TEAM ${clubStrength()}`;document.getElementById('opponentTeamRating').textContent=`TEAM ${rating}`;document.getElementById('matchCompetitionLabel').textContent=activeDef().name.toUpperCase();document.getElementById('matchRoundTag').textContent=state.seasonStage==='playoffs'?'KNOCKOUTS':state.seasonStage.toUpperCase();document.getElementById('matchStatus').textContent=f?'READY':'SEASON COMPLETE';document.getElementById('simulateBtn').textContent=state.seasonStage==='complete'?'Start next season':state.seasonStage==='playoffs'?(f?.name||'Playoffs')+' · Play match':'▶ Play next match';document.getElementById('simulateBtn').disabled=!f&&state.seasonStage!=='complete';document.getElementById('fixtureFormat').textContent=state.format;document.getElementById('matchOvers').textContent=document.getElementById('matchFormat').value==='ODI'?'50 OVERS':'20 OVERS';}
function renderBracket(){const el=document.getElementById('playoffBracket');if(state.seasonStage==='league'){el.innerHTML=`<div class="bracket-stage"><b>League stage</b><p>${Math.max(0,state.fixtures.length-state.round)} rounds remaining</p><small>Top four qualify</small></div>`;return;}el.innerHTML=state.playoffs.map(f=>`<div class="bracket-stage ${f.played?'completed':''}"><b>${esc(f.name)}</b><p>${esc(f.home||'TBD')} <strong>vs</strong> ${esc(f.away||'TBD')}</p><small>${f.played?'Winner: '+esc(f.winner):'Awaiting match'}</small></div>`).join('')||'<p class="muted">Playoffs begin after the league stage.</p>';}
function renderCompetitions(){document.getElementById('tournamentGrid').innerHTML=leagueDefs.map(l=>`<article class="panel tournament-card ${state.activeLeague===l.id?'selected':''}"><div class="tournament-icon">${l.flag}</div><span class="eyebrow">${l.country.toUpperCase()}</span><h3>${l.name}</h3><p>${l.size} clubs · T20 + ODI</p><div class="market-meta"><span>Championship prize</span><b>${money(l.prize)}</b></div><div class="club-chip-list">${worldTeams[l.id].slice(0,4).map(t=>`<span>${t.badge} ${esc(t.name)}</span>`).join('')}${l.size>4?`<span>+${l.size-4} clubs</span>`:''}</div><button class="primary-btn" data-view-league="${l.id}">View clubs</button></article>`).join('');document.querySelectorAll('[data-view-league]').forEach(b=>b.addEventListener('click',()=>{const l=leagueDefs.find(x=>x.id===b.dataset.viewLeague);const clubs=worldTeams[l.id].map(t=>`${t.badge} ${t.name} (${t.strength})`).join('\n');alert(`${l.name}\n${l.size} clubs\n\n${clubs}\n\nYou can receive job proposals from clubs in this competition.`);}));}
function renderSquad(){document.getElementById('squadTable').innerHTML=state.players.map(p=>`<tr><td><div class="player-cell"><div class="player-avatar">${esc(p.name.split(' ').map(x=>x[0]).join('').slice(0,2))}</div><b>${esc(p.name)}</b></div></td><td><span class="role-pill">${esc(p.role)}</span></td><td>${p.age}</td><td class="rating">${p.rating}</td><td>${Math.round(p.form||70)}</td><td>${money(p.value)}</td><td><button class="sell-btn" data-release="${p.id}">Release</button></td></tr>`).join('');document.querySelectorAll('[data-release]').forEach(b=>b.addEventListener('click',()=>releasePlayer(Number(b.dataset.release))));document.getElementById('squadCount').textContent=state.players.length+' PLAYERS';}
function renderMarket(){const q=(document.getElementById('marketSearch')?.value||'').toLowerCase(),role=document.getElementById('marketRole')?.value||'all';const owned=new Set(state.players.map(p=>p.id));const list=transferPlayers.filter(p=>!owned.has(p.id)&&(!q||(p.name+' '+p.role).toLowerCase().includes(q))&&(role==='all'||p.role===role));document.getElementById('marketGrid').innerHTML=list.map(p=>`<article class="market-card"><div class="market-top"><div class="market-avatar">${p.name.split(' ').map(x=>x[0]).join('')}</div><span class="rating">${p.rating} OVR</span></div><h3>${esc(p.name)}</h3><p>${esc(p.role)} · Age ${p.age} · Form ${70+(p.id%25)}</p><div class="market-meta"><span>Transfer value</span><b>${money(p.value)}</b></div><button class="primary-btn" data-sign="${p.id}" ${state.budget<p.value?'disabled':''}>${state.budget<p.value?'Insufficient budget':'Sign player'}</button></article>`).join('')||'<p class="muted">No available players match this search.</p>';document.querySelectorAll('[data-sign]').forEach(b=>b.addEventListener('click',()=>signPlayer(Number(b.dataset.sign))));document.getElementById('transferBudget').textContent='Budget: '+money(state.budget);}
function signPlayer(id){const p=transferPlayers.find(x=>x.id===id);if(!p||state.players.some(x=>x.id===id)||state.budget<p.value)return;state.budget-=p.value;state.players.push({...p,form:70+(p.id%25),morale:state.morale});addNews(`${p.name} signed for ${money(p.value)}.`,'TRANSFER');save();toast('Player signed. Squad rating updated.');}
function releasePlayer(id){if(state.players.length<=11){toast('Keep at least 11 players in your squad.');return;}const i=state.players.findIndex(p=>p.id===id);if(i<0)return;const p=state.players.splice(i,1)[0];state.budget+=Math.round(p.value*.65);addNews(`${p.name} released. 65% of value returned.`,'TRANSFER');save();}
function renderTactics(){const t=state.tactics;['batting','bowling','powerplay','death','field'].forEach(k=>{const el=document.getElementById(k+'Tactic');if(el)el.value=t[k];});document.getElementById('captainSelect').innerHTML=state.players.map(p=>`<option value="${p.id}">${esc(p.name)} · ${p.rating}</option>`).join('');if(t.captain)document.getElementById('captainSelect').value=t.captain;const mods=[];mods.push(`Batting: ${t.batting==='Aggressive'?'+5 scoring / higher wicket risk':t.batting==='Defensive'?'-4 scoring / wicket protection':'balanced scoring'}`);mods.push(`Bowling: ${t.bowling==='Contain'?'+3 control':t.bowling==='Pace'?'+2 pace':'spin/mixed match-up bonus'}`);mods.push(`Field: ${t.field==='Attacking'?'+2 wicket pressure':t.field==='Defensive'?'+1 run control':'balanced field'}`);document.getElementById('tacticAnalysis').innerHTML=mods.map(x=>`<div class="analysis-row">${esc(x)}</div>`).join('');}
document.getElementById('saveTactics').addEventListener('click',()=>{['batting','bowling','powerplay','death','field'].forEach(k=>state.tactics[k]=document.getElementById(k+'Tactic').value);state.tactics.captain=document.getElementById('captainSelect').value;addNews(`Tactical plan updated: ${state.tactics.batting} batting, ${state.tactics.bowling} bowling.`,'TACTICS');save();toast('Tactics saved and will affect match simulation.');});
function renderScouting(){document.getElementById('scoutReport').innerHTML=state.scoutReports.length?state.scoutReports.slice(0,8).map(r=>`<div class="report-item"><b>${esc(r.name)}</b><span>${esc(r.role)} · ${r.age} years · ${r.rating} OVR</span><small>${esc(r.region)} scouting report · ${money(r.value)}</small><button class="secondary-btn" data-scout-sign="${r.id}">Sign for ${money(r.value)}</button></div>`).join(''):'No scouting reports yet.';document.querySelectorAll('[data-scout-sign]').forEach(b=>b.addEventListener('click',()=>{const p=state.scoutReports.find(x=>x.id===Number(b.dataset.scoutSign));if(!p||state.budget<p.value)return toast('Insufficient club budget.');state.budget-=p.value;state.players.push({...p,form:72,morale:state.morale});state.scoutReports=state.scoutReports.filter(x=>x.id!==p.id);addNews(`Scouted prospect ${p.name} signed.`,'SCOUTING');save();}));}
document.getElementById('runScout').addEventListener('click',()=>{if(state.budget<75)return toast('Insufficient budget for scouting.');state.budget-=75;const focus=document.getElementById('scoutFocus').value,region=document.getElementById('scoutRegion').value;const role=focus==='Any'?rolePool[Math.floor(Math.random()*rolePool.length)]:focus;const rating=68+Math.floor(Math.random()*25);const p={id:5000+state.gameDay+Math.floor(Math.random()*100000),name:firstNames[Math.floor(Math.random()*firstNames.length)]+' '+lastNames[Math.floor(Math.random()*lastNames.length)],role,age:18+Math.floor(Math.random()*8),rating,value:Math.round(rating*rating*.32),region,form:72,morale:75};state.scoutReports.unshift(p);addNews(`Scouting department found ${p.name} (${rating} OVR) in ${region}.`,'SCOUTING');save();toast('New scouting report received.');});
function renderAcademy(){document.getElementById('academyLevel').textContent=state.academyLevel;document.getElementById('academyInvestment').textContent=money(state.academyLevel*500);document.getElementById('academyList').innerHTML=state.youth.map(p=>`<div class="report-item"><b>${esc(p.name)}</b><span>${p.role} · Age ${p.age} · ${p.rating} OVR</span><small>Development: ${p.progress||0}%</small><button class="secondary-btn" data-train="${p.id}">Train · ₹50K</button><button class="secondary-btn" data-promote="${p.id}">Promote to senior squad</button></div>`).join('')||'<p class="muted">No academy prospects yet. Generate a youth player to begin.</p>';document.querySelectorAll('[data-train]').forEach(b=>b.addEventListener('click',()=>trainYouth(Number(b.dataset.train))));document.querySelectorAll('[data-promote]').forEach(b=>b.addEventListener('click',()=>promoteYouth(Number(b.dataset.promote))));}
document.getElementById('upgradeAcademy').addEventListener('click',()=>{const cost=state.academyLevel*500;if(state.budget<cost)return toast('Insufficient budget.');state.budget-=cost;state.academyLevel++;addNews(`Youth academy upgraded to level ${state.academyLevel}.`,'ACADEMY');save();});
document.getElementById('generateYouth').addEventListener('click',()=>{if(state.budget<150)return toast('Insufficient budget.');state.budget-=150;const role=rolePool[Math.floor(Math.random()*rolePool.length)],rating=55+state.academyLevel*3+Math.floor(Math.random()*8);state.youth.push({id:9000+state.gameDay+Math.floor(Math.random()*100000),name:firstNames[Math.floor(Math.random()*firstNames.length)]+' '+lastNames[Math.floor(Math.random()*lastNames.length)],role,age:16+Math.floor(Math.random()*4),rating:Math.min(79,rating),value:Math.round(rating*rating*.25),progress:0});addNews('Academy prospect generated. The coaching team has identified a young talent.','ACADEMY');save();});
function trainYouth(id){const p=state.youth.find(x=>x.id===id);if(!p||state.budget<50)return toast('Insufficient budget.');state.budget-=50;p.rating=Math.min(95,p.rating+1+Math.floor(state.academyLevel/3));p.progress=Math.min(100,(p.progress||0)+20);addNews(`${p.name} improved to ${p.rating} OVR in academy training.`,'ACADEMY');save();}
function promoteYouth(id){const p=state.youth.find(x=>x.id===id);if(!p)return;if(state.players.length>=25)return toast('Senior squad limit is 25 players.');state.players.push({...p,age:Math.max(18,p.age),form:70,morale:state.morale});state.youth=state.youth.filter(x=>x.id!==id);addNews(`${p.name} promoted to the senior squad.`,'ACADEMY');save();}
function renderMorale(){document.getElementById('moraleScore').textContent=state.morale;document.getElementById('moraleBar').style.width=state.morale+'%';document.getElementById('moraleMessage').textContent=state.morale>80?'Excellent atmosphere. Players are highly motivated.':state.morale>60?'A settled dressing room is ready for the season.':state.morale>40?'Morale is fragile. Consider a team meeting.':'The squad is unhappy. Results and communication need attention.';document.getElementById('moralePlayers').innerHTML=state.players.slice(0,10).map(p=>`<div class="analysis-row">${esc(p.name)} <b>${p.morale||70}% morale</b></div>`).join('');}
document.getElementById('teamMeeting').addEventListener('click',()=>{if(state.budget<25)return toast('Insufficient budget.');state.budget-=25;state.morale=Math.min(100,state.morale+12);state.players.forEach(p=>p.morale=Math.min(100,(p.morale||70)+10));addNews('Manager held a squad meeting. Dressing-room morale improved.','DRESSING ROOM');save();toast('Team morale improved.');});
function setPressPrompt(question,choices){state.pressPrompt={question,choices};renderPress();}
function maybeAwardPressPrompt(){setPressPrompt('Your team delivered a strong performance. What message will you send to the media?', [['Praise the players',2,3],['Credit the coaching staff',1,1],['Stay focused on the next fixture',0,2]]);}
function renderPress(){const p=state.pressPrompt||{question:'The media are waiting for your first statement.',choices:[['Praise the club',1,2],['Stay professional',0,1],['Challenge expectations',-1,-1]]};document.getElementById('pressQuestion').textContent=p.question;document.getElementById('pressChoices').innerHTML=p.choices.map((c,i)=>`<button class="press-choice" data-press="${i}">${esc(c[0])}</button>`).join('');document.querySelectorAll('[data-press]').forEach(b=>b.addEventListener('click',()=>{const c=state.pressPrompt.choices[Number(b.dataset.press)];state.boardConfidence=Math.max(0,Math.min(100,state.boardConfidence+c[1]));state.morale=Math.max(0,Math.min(100,state.morale+c[2]));document.getElementById('pressOutcome').textContent=`Your response affected board confidence by ${c[1]>=0?'+':''}${c[1]} and squad morale by ${c[2]>=0?'+':''}${c[2]}.`;addNews(`Press conference: manager said "${c[0]}".`,'PRESS CONFERENCE');state.pressPrompt=null;save();}));}
function renderStadium(){const cap=12000+(state.stadiumLevel-1)*6500;document.getElementById('stadiumLevel').textContent=state.stadiumLevel;document.getElementById('stadiumCapacity').textContent=cap.toLocaleString('en-IN');document.getElementById('homeAdvantage').textContent='+'+(1+(state.stadiumLevel-1)*.6).toFixed(1);}
document.getElementById('upgradeStadium').addEventListener('click',()=>{const cost=750*state.stadiumLevel;if(state.budget<cost)return toast('Insufficient budget.');state.budget-=cost;state.stadiumLevel++;addNews(`Stadium development completed. Stadium level ${state.stadiumLevel}.`,'STADIUM');save();});
function clubProposalPool(){return leagueDefs.flatMap(l=>worldTeams[l.id].map(t=>({...t,leagueName:l.name,salary:Math.max(327,Math.round((t.strength-60)**2*22)),budget:Math.max(3500,Math.round(t.strength*t.strength*.75)),contract:2}))).filter(t=>t.name!==state.club.name&&t.strength<=state.managerRating+15&&t.strength>=state.managerRating-22);}
function generateOffers(){const pool=clubProposalPool().sort(()=>Math.random()-.5);state.jobOffers=pool.slice(0,3);if(!state.jobOffers.length){const all=clubProposalPoolAll().filter(t=>t.name!==state.club.name).sort((a,b)=>Math.abs(a.strength-state.managerRating)-Math.abs(b.strength-state.managerRating));state.jobOffers=all.slice(0,2);}state.lastProposalDay=state.gameDay;addNews(`${state.jobOffers.length} clubs have contacted your agent with managerial proposals.`,'MANAGER MARKET');save();if(state.jobOffers.length)openProposal(state.jobOffers[0]);}
function clubProposalPoolAll(){return leagueDefs.flatMap(l=>worldTeams[l.id].map(t=>({...t,leagueName:l.name,salary:Math.max(327,Math.round((t.strength-60)**2*22)),budget:Math.max(3500,Math.round(t.strength*t.strength*.75)),contract:2})));}
function openProposal(c){proposalTarget=c;document.getElementById('proposalBadge').textContent=c.badge;document.getElementById('proposalClub').textContent=c.name;document.getElementById('proposalLeague').textContent=c.leagueName;document.getElementById('proposalStats').innerHTML=`<div><small>Club rating</small><b>${c.strength}/100</b></div><div><small>Weekly salary</small><b>${rupees(c.salary)}</b></div><div><small>Transfer budget</small><b>${money(c.budget)}</b></div><div><small>Contract</small><b>${c.contract} seasons</b></div>`;document.getElementById('proposalDeadline').textContent='The club expects a decision. Negotiation can improve salary, but may cause the offer to be withdrawn.';document.getElementById('proposalModal').classList.remove('hidden');}
function closeProposal(){document.getElementById('proposalModal').classList.add('hidden');}
document.getElementById('closeProposal').addEventListener('click',closeProposal);document.getElementById('rejectProposal').addEventListener('click',()=>{if(proposalTarget){addNews(`Manager rejected the offer from ${proposalTarget.name}.`,'MANAGER MARKET');state.jobOffers=state.jobOffers.filter(x=>x.name!==proposalTarget.name);save();}closeProposal();});
document.getElementById('negotiateProposal').addEventListener('click',()=>{if(!proposalTarget)return;const c=proposalTarget;if(state.managerRating<c.strength-8){toast('The board will not improve this offer at your current reputation.');return;}c.salary=Math.round(c.salary*1.18);document.getElementById('proposalStats').innerHTML=`<div><small>Club rating</small><b>${c.strength}/100</b></div><div><small>Negotiated weekly salary</small><b>${rupees(c.salary)}</b></div><div><small>Transfer budget</small><b>${money(c.budget)}</b></div><div><small>Contract</small><b>${c.contract} seasons</b></div>`;document.getElementById('proposalDeadline').textContent='Negotiation accepted. The improved salary is now available.';toast('Offer improved by 18%.');});
document.getElementById('acceptProposal').addEventListener('click',()=>{if(!proposalTarget)return;const c=proposalTarget,old=state.club.name;state.club=worldTeams[c.league].find(t=>t.name===c.name);state.resigned=false;state.activeLeague=c.league;state.budget=c.budget;state.weeklySalary=c.salary;state.careerClubs.unshift(c.name);state.careerTimeline.unshift(`Day ${state.gameDay} · Appointed manager of ${c.name} (${c.leagueName}).`);state.jobOffers=state.jobOffers.filter(x=>x.name!==c.name);setupSeason();addNews(`BREAKING: ${state.managerName} appointed manager of ${c.name} in ${c.leagueName}.`,'MANAGER APPOINTMENT');closeProposal();save();toast('New club contract signed. New league season loaded.');});
document.getElementById('refreshOffers').addEventListener('click',generateOffers);
function renderJobs(){document.getElementById('jobRating').textContent='RATING '+state.managerRating;document.getElementById('currentJobClub').textContent=state.club.name;document.getElementById('currentJobSalary').textContent=rupees(state.weeklySalary);document.getElementById('jobNavCount').textContent=state.jobOffers.length?'('+state.jobOffers.length+')':'';document.getElementById('jobOffers').innerHTML=state.jobOffers.map((c,i)=>`<article class="panel job-card"><div class="job-card-top"><span>${c.badge}</span><b>${c.strength} OVR CLUB</b></div><h3>${esc(c.name)}</h3><p>${esc(c.leagueName)}</p><div class="market-meta"><span>Weekly salary</span><b>${rupees(c.salary)}</b></div><button class="primary-btn" data-open-job="${i}">Review proposal</button></article>`).join('')||'<p class="muted">No active offers. Request proposals to see which clubs are interested.</p>';document.querySelectorAll('[data-open-job]').forEach(b=>b.addEventListener('click',()=>openProposal(state.jobOffers[Number(b.dataset.openJob)])));}
function renderLegacy(){document.getElementById('legacyWins').textContent=state.careerWins;document.getElementById('legacyLosses').textContent=state.careerLosses;document.getElementById('legacyTrophies').textContent=state.careerTrophies;document.getElementById('legacyClubs').textContent=new Set(state.careerClubs).size||1;document.getElementById('careerTimeline').innerHTML=(state.careerTimeline||[]).map(x=>`<div class="news-item">${esc(x)}</div>`).join('')||'<p class="muted">Your career timeline will appear here.</p>';}
function renderClub(){const c=state.club;document.getElementById('clubPageName').textContent=c.name;document.getElementById('profileClubName').textContent=c.name;document.getElementById('profileBadge').textContent=c.badge;document.getElementById('profileLeague').textContent=activeDef().name;document.getElementById('profileRating').textContent=clubStrength()+'/100';document.getElementById('profileBudget').textContent=money(state.budget);document.getElementById('profileStadium').textContent=c.stadium;document.getElementById('clubBoard').textContent=state.boardConfidence+'%';document.getElementById('clubMorale').textContent=state.morale;document.getElementById('clubTrophies').textContent=state.careerTrophies;document.getElementById('clubFans').textContent=state.fans.toLocaleString('en-IN');}
function renderAll(){if(!state.managerName||!state.club)return;const c=state.club;document.getElementById('sideClubName').textContent=c.name;document.getElementById('sideLeague').textContent=activeDef().short+' · '+activeDef().country;document.getElementById('clubBadge').textContent=c.badge;document.getElementById('dashFans').textContent=state.fans.toLocaleString('en-IN');document.getElementById('dashSquad').textContent=state.players.length;document.getElementById('dashMoney').textContent=money(state.budget);document.getElementById('dashRating').textContent=state.managerRating;document.getElementById('managerDashName').textContent=state.managerName;document.getElementById('boardConfidence').textContent=state.boardConfidence;document.getElementById('managerAvatar').textContent=state.managerName[0].toUpperCase();document.getElementById('activeLeagueLabel').textContent=activeDef().short;document.getElementById('gameDateLabel').textContent=`Season ${state.season} · Game day ${state.gameDay}`;document.getElementById('clubStrength').textContent=clubStrength()+'/100';const mine=state.table?.[state.club.name]||{played:0,points:0};document.getElementById('clubRecord').textContent=`${mine.played} played · ${mine.points} points`;document.getElementById('managerWallet').textContent=rupees(state.managerWallet);document.getElementById('weeklySalary').textContent=rupees(state.weeklySalary);document.getElementById('nextPayday').textContent=(7-((state.gameDay-state.lastSalaryDay)%7))+' days';document.getElementById('saveSlotLabel').textContent=`Save slot ${activeSlot} · Local`;document.getElementById('seasonPill').textContent=`SEASON ${state.season}`;document.getElementById('newsList').innerHTML=state.news.slice(0,9).map(n=>`<div class="news-item"><span class="news-category">${esc(n.category)}</span><b>DAY ${n.day}</b><p>${esc(n.text)}</p></div>`).join('');renderTable();renderFixture();renderSquad();renderMarket();renderTactics();renderScouting();renderAcademy();renderMorale();renderPress();renderStadium();renderLegacy();renderClub();renderJobs();renderCompetitions();renderBracket();}
function switchSlot(slot){activeSlot=slot;state=loadSlot(slot);if(!state.managerName){document.getElementById('careerSetup').classList.remove('hidden');document.getElementById('startSaveSlot').value=String(slot);}else{document.getElementById('careerSetup').classList.add('hidden');save();}document.getElementById('slotModal').classList.add('hidden');}
document.getElementById('saveSlotsBtn').addEventListener('click',()=>{document.getElementById('slotList').innerHTML=[1,2,3].map(n=>{const s=loadSlot(n);return`<button class="slot-choice" data-slot="${n}"><b>Career slot ${n}</b><span>${s.managerName?esc(s.managerName)+' · '+esc(s.club?.name||'Club'):'Empty slot'}</span></button>`;}).join('');document.querySelectorAll('[data-slot]').forEach(b=>b.addEventListener('click',()=>switchSlot(Number(b.dataset.slot))));document.getElementById('slotModal').classList.remove('hidden');});document.getElementById('closeSlots').addEventListener('click',()=>document.getElementById('slotModal').classList.add('hidden'));
document.getElementById('resetBtn').addEventListener('click',()=>{if(confirm('Start a new career in the current save slot? This replaces the current slot.')){localStorage.removeItem(SAVE_PREFIX+activeSlot);state=freshState(activeSlot);document.getElementById('careerSetup').classList.remove('hidden');document.getElementById('startSaveSlot').value=String(activeSlot);}});
document.getElementById('marketSearch').addEventListener('input',renderMarket);document.getElementById('marketRole').addEventListener('change',renderMarket);document.getElementById('matchFormat').addEventListener('change',()=>{state.format=document.getElementById('matchFormat').value;document.getElementById('matchOvers').textContent=state.format==='ODI'?'50 OVERS':'20 OVERS';});document.getElementById('simulateBtn').addEventListener('click',()=>{if(state.seasonStage==='complete'){startNextSeason();return;}const f=nextFixture();if(!f){if(state.seasonStage==='league'){advanceLeagueRound();save();}else{advancePlayoffsAuto();save();}return;}if(state.seasonStage==='league'){const round=state.fixtures[state.round];finishUserMatch(f,`ROUND ${state.round+1}`);round.forEach(x=>{if(!x.played)simulateAIFixture(x);});state.round++;if(state.round>=state.fixtures.length)beginPlayoffs();}else{const outcome=playUserFixture(f);f.played=true;f.winner=outcome.userWon?state.club.name:outcome.opponent;f.loser=outcome.userWon?outcome.opponent:state.club.name;f.result=outcome.result;state.played++;state.careerWins+=outcome.userWon?1:0;state.careerLosses+=outcome.userWon?0:1;state.wins+=outcome.userWon?1:0;state.losses+=outcome.userWon?0:1;state.managerRating=Math.max(1,Math.min(100,state.managerRating+(outcome.userWon?3:-2)));state.boardConfidence=Math.max(0,Math.min(100,state.boardConfidence+(outcome.userWon?6:-5)));state.morale=Math.max(10,Math.min(100,state.morale+(outcome.userWon?6:-6)));state.budget+=outcome.userWon?650:200;addNews(`${f.name}: ${f.winner} advanced after defeating ${f.loser}.`,'KNOCKOUT');renderMatchReport(outcome,f.name,Math.abs(outcome.ownScore.runs-outcome.oppScore.runs));state.playoffIndex++;if(state.playoffIndex===2){const q1=state.playoffs[0],el=state.playoffs[1];state.playoffs.push({name:'Qualifier 2',home:q1.loser,away:el.winner,played:false,winner:null});}else if(state.playoffIndex===3){state.playoffs.push({name:'Grand Final',home:state.playoffs[0].winner,away:state.playoffs[2].winner,played:false,winner:null});}else if(state.playoffIndex>=4)completeSeason();advancePlayoffsAuto();}paySalary();save();});
document.getElementById('runScout').addEventListener('keydown',()=>{});
document.getElementById('closeProposal').addEventListener('keydown',()=>{});
function maybeAutoProposal(){if(state.managerName&&state.gameDay-state.lastProposalDay>=14&&state.managerRating>=68&&state.jobOffers.length===0){const pool=clubProposalPool();if(pool.length){state.jobOffers=pool.slice(0,2);state.lastProposalDay=state.gameDay;addNews(`Transfer rumour: ${state.jobOffers[0].name} are preparing an approach for ${state.managerName}.`,'MANAGER MARKET');setTimeout(()=>{if(state.jobOffers.length)openProposal(state.jobOffers[0]);},250);}}}
